<template><view class="page"><view class="content"><view class="ai-head"><view class="ai-icon">✦</view><view><view class="big">智能定制</view><view>告诉我偏好，30 秒匹配专属路线</view></view></view><view class="card"><view class="form-item" v-for="f in fields" :key="f.label"><view class="label">{{f.label}} <text class="sub">{{f.tip}}</text></view><view class="choices"><view v-for="o in f.opts" :key="o" class="choice" :class="{on:f.selected.includes(o)}" @click="toggle(f,o)">{{o}}</view></view></view><view class="form-item"><view class="label">积分预算区间</view><slider min="1000" max="10000" value="4000" activeColor="#12a594"/><view class="title-row sub"><text>1,000 积分</text><text>当前约 4,000 积分/人</text><text>10,000+ 积分</text></view></view></view></view><view class="fixed-action"><view class="btn btn-green" @click="match">✦ 一键匹配路线</view></view></view></template><script setup>import{reactive}from'vue';const fields=reactive([{label:'目的地偏好',tip:'可多选',opts:['西南秘境','海滨城市','西北旷野','江南古镇'],selected:['西南秘境']},{label:'出行天数',tip:'单选',opts:['2-3 天','4-5 天','6-7 天','8 天以上'],selected:['4-5 天']},{label:'旅行主题',tip:'可多选',opts:['户外徒步','人文研学','美食探索','旅拍出片','毕业团建'],selected:['户外徒步','旅拍出片']},{label:'出行人数',tip:'单选',opts:['1 人','2 人','3-5 人','6 人以上'],selected:['2 人']}]);const toggle=(f,o)=>{if(f.tip==='单选')f.selected=[o];else f.selected.includes(o)?f.selected.splice(f.selected.indexOf(o),1):f.selected.push(o)};const match=()=>uni.navigateTo({url:'/pages/travel/index'})</script><style scoped>.ai-head{background:linear-gradient(135deg,#0d675e,#16ab9a);color:#fff;border-radius:32rpx;padding:40rpx;display:flex;align-items:center;margin-bottom:22rpx}.ai-icon{font-size:70rpx;margin-right:24rpx}</style>
